package com.schwab.urlshortener.service;

import com.schwab.urlshortener.exception.SsrfBlockedException;
import java.net.InetAddress;
import java.net.UnknownHostException;
import org.springframework.stereotype.Component;

/**
 * Resolves the target URL's hostname to IP addresses and rejects private,
 * loopback, link-local, and multicast ranges to prevent SSRF attacks.
 */
@Component
public class SsrfGuard {

    /**
     * Validates that the given URL does not point to a restricted IP range.
     *
     * @param url the URL to validate
     * @throws SsrfBlockedException if the hostname resolves to a blocked IP range
     */
    public void validate(java.net.URL url) {
        String host = url.getHost();
        InetAddress[] addresses;
        try {
            addresses = InetAddress.getAllByName(host);
        } catch (UnknownHostException e) {
            throw new SsrfBlockedException("Unable to resolve host: " + host, e);
        }

        for (InetAddress address : addresses) {
            if (isBlocked(address)) {
                throw new SsrfBlockedException(
                    "Blocked SSRF attempt to restricted IP address: " + address.getHostAddress()
                        + " for host: " + host
                );
            }
        }
    }

    private boolean isBlocked(InetAddress address) {
        // Loopback: 127.x.x.x / ::1
        if (address.isLoopbackAddress()) {
            return true;
        }

        // Link-local: 169.254.x.x / fe80::/10
        if (address.isLinkLocalAddress()) {
            return true;
        }

        // Multicast: 224.x.x.x - 239.x.x.x / ff00::/8
        if (address.isMulticastAddress()) {
            return true;
        }

        // Site-local (private): 10.x.x.x, 172.16.x.x-172.31.x.x, 192.168.x.x / fc00::/7
        if (address.isSiteLocalAddress()) {
            return true;
        }

        // Any local address
        if (address.isAnyLocalAddress()) {
            return true;
        }

        byte[] bytes = address.getAddress();

        // IPv4 checks
        if (bytes.length == 4) {
            int b0 = bytes[0] & 0xFF;
            int b1 = bytes[1] & 0xFF;

            // 0.x.x.x - "this" network
            if (b0 == 0) {
                return true;
            }

            // 100.64.x.x - 100.127.x.x (Shared Address Space, RFC 6598)
            if (b0 == 100 && b1 >= 64 && b1 <= 127) {
                return true;
            }

            // 192.0.0.x (IETF Protocol Assignments)
            if (b0 == 192 && b1 == 0 && (bytes[2] & 0xFF) == 0) {
                return true;
            }

            // 192.0.2.x, 198.51.100.x, 203.0.113.x (Documentation ranges)
            if (b0 == 192 && b1 == 0 && (bytes[2] & 0xFF) == 2) {
                return true;
            }
            if (b0 == 198 && b1 == 51 && (bytes[2] & 0xFF) == 100) {
                return true;
            }
            if (b0 == 203 && b1 == 0 && (bytes[2] & 0xFF) == 113) {
                return true;
            }

            // 198.18.x.x - 198.19.x.x (Benchmarking)
            if (b0 == 198 && (b1 == 18 || b1 == 19)) {
                return true;
            }

            // 240.x.x.x - 255.x.x.x (Reserved)
            if (b0 >= 240) {
                return true;
            }
        }

        // IPv6 checks
        if (bytes.length == 16) {
            // Unique local: fc00::/7
            if ((bytes[0] & 0xFE) == 0xFC) {
                return true;
            }
        }

        return false;
    }
}


