package com.schwab.urlshortener.config;

import java.net.http.HttpClient;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * Constructs a java.net.http.HttpClient bean used exclusively by UrlPreviewService.
 * Configured with NO_REDIRECT to refuse redirect following, keeping isolation
 * from any future beans.
 */
@Configuration
public class PreviewHttpClientConfig {

    @Bean(name = "previewHttpClient")
    public HttpClient previewHttpClient() {
        return HttpClient.newBuilder()
            .followRedirects(HttpClient.Redirect.NEVER)
            .build();
    }
}


