package com.schwab.urlshortener.config;

import com.schwab.urlshortener.domain.PreviewResult;
import java.time.Duration;
import org.springframework.boot.context.properties.EnableConfigurationProperties;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * Declares an in-process cache for PreviewResult, keyed by shortCode.
 * Uses a TimedCache (LRU + TTL) since Caffeine is not on the classpath.
 * expireAfterWrite = configured value (default 1h), maximumSize = configured value (default 10_000).
 */
@Configuration
@EnableConfigurationProperties(PreviewProperties.class)
public class PreviewCacheConfig {

    @Bean(name = "previewCache")
    public TimedCache<String, PreviewResult> previewCache(PreviewProperties previewProperties) {
        int maxSize = previewProperties.cache().maxSize();
        long expireAfterWriteSeconds = previewProperties.cache().expireAfterWriteSeconds();
        return new TimedCache<>(maxSize, Duration.ofSeconds(expireAfterWriteSeconds));
    }
}


